"""Tests for MocapRunService: the job for the worker, checking the panel settings, reading the worker messages,
and a whole run with a fake worker script (blender's own python), so no models or environment are needed."""

import json
import os
import sys
import textwrap

import bpy
import pytest

from .. import dynamic_import

MocapRunService = dynamic_import("mpfb.services.mocaprunservice", "MocapRunService")
_MODULE = sys.modules[MocapRunService.__module__]
RunJob = _MODULE.RunJob
TaskState = _MODULE.TaskState

_REGISTRY = {"models": [
    {"id": "mediapipe_pose_lite", "files": [{"path": "mediapipe/pose_landmarker_lite.task"}]},
    {"id": "mediapipe_pose_full", "files": [{"path": "mediapipe/pose_landmarker_full.task"}]},
    {"id": "mediapipe_pose_heavy", "files": [{"path": "mediapipe/pose_landmarker_heavy.task"}]},
    {"id": "mediapipe_hand", "files": [{"path": "mediapipe/hand_landmarker.task"}]},
    {"id": "mediapipe_face", "files": [{"path": "mediapipe/face_landmarker.task"}]},
    {"id": "wav2vec2_xlsr53_espeak", "files": [{"path": "w2v/config.json"}, {"path": "w2v/vocab.json"}]},
    ]}


def _video(**overrides):
    video = {"path": "", "pose": True, "hands": True, "face": False, "pose_model": "FULL", "min_confidence": 0.5,
             "start": 0.0, "end": 0.0, "annotate": True}
    video.update(overrides)
    return video


def _settings(videos=(), **overrides):
    settings = {"videos": list(videos), "audio_path": "", "audio_start": 0.0, "audio_end": 0.0, "audio_device": "AUTO"}
    settings.update(overrides)
    return settings


def test_service_is_not_instanced():
    with pytest.raises(RuntimeError):
        MocapRunService()


def test_worker_script_ships_with_mpfb():
    assert os.path.isfile(MocapRunService.get_worker_script())


def test_worker_is_not_a_package():
    """Blender must never import the worker, it would pull mediapipe and torch into blender's python."""
    assert not os.path.exists(os.path.join(os.path.dirname(MocapRunService.get_worker_script()), "__init__.py"))


def test_job_with_both_inputs():
    video = _video(path="/v.mp4", pose_model="HEAVY", hands=False, face=True, start=1.5, end=4.0)
    job = MocapRunService.build_job(_settings([video], audio_path="/a.wav"), "/out", "/models", _REGISTRY)
    assert job["protocol"] == _MODULE.PROTOCOL_VERSION
    vision, audio = job["tasks"]
    assert vision["id"] == "video1" and vision["type"] == "vision" and vision["input"] == "/v.mp4"
    assert vision["label"] == "Video: v.mp4"
    assert vision["pose"] == {"enabled": True, "model": "mediapipe/pose_landmarker_heavy.task"}
    assert vision["hands"]["enabled"] is False
    assert vision["face"] == {"enabled": True, "model": "mediapipe/face_landmarker.task"}
    assert (vision["start"], vision["end"]) == (1.5, 4.0)
    assert audio["type"] == "audio" and audio["model"] == "w2v" and audio["device"] == "auto"


def test_job_with_several_videos():
    videos = [_video(path="/front.mp4", face=True), _video(path="/side.mp4", pose_model="LITE"), _video(path="")]
    job = MocapRunService.build_job(_settings(videos), "/out", "/models", _REGISTRY)
    assert [task["id"] for task in job["tasks"]] == ["video1", "video2"]
    assert [task["label"] for task in job["tasks"]] == ["Video 1: front.mp4", "Video 2: side.mp4"]
    assert job["tasks"][1]["pose"]["model"] == "mediapipe/pose_landmarker_lite.task"
    assert job["tasks"][1]["face"]["enabled"] is False


def test_job_skips_empty_inputs():
    job = MocapRunService.build_job(_settings(audio_path="/a.wav"), "/out", "/models", _REGISTRY)
    assert [task["id"] for task in job["tasks"]] == ["audio"]


def test_settings_without_inputs_are_rejected():
    assert MocapRunService.validate_settings(_settings())


def test_settings_with_missing_file_are_rejected(tmp_path):
    problems = MocapRunService.validate_settings(_settings([_video(path=str(tmp_path / "nope.mp4"))]))
    assert any("does not exist" in problem for problem in problems)


def test_settings_with_no_model_or_bad_range_are_rejected(tmp_path):
    video = tmp_path / "clip.mp4"
    video.write_bytes(b"")
    path = str(video)
    assert MocapRunService.validate_settings(_settings([_video(path=path, pose=False, hands=False, face=False)]))
    assert MocapRunService.validate_settings(_settings([_video(path=path, start=3.0, end=2.0)]))
    assert not MocapRunService.validate_settings(_settings([_video(path=path, start=3.0, end=0.0)]))


def test_only_one_video_can_have_the_face(tmp_path):
    first, second = tmp_path / "a.mp4", tmp_path / "b.mp4"
    first.write_bytes(b"")
    second.write_bytes(b"")
    two_faces = [_video(path=str(first), face=True), _video(path=str(second), face=True)]
    assert any("face" in problem for problem in MocapRunService.validate_settings(_settings(two_faces)))
    one_face = [_video(path=str(first), face=True), _video(path=str(second))]
    assert not MocapRunService.validate_settings(_settings(one_face))


def test_worker_messages_update_the_job():
    job = RunJob("/out")
    job.tasks["video"] = TaskState("video", "Video / image")
    prefix = _MODULE.MESSAGE_PREFIX
    MocapRunService.handle_line(job, prefix + json.dumps({"event": "task_start", "task": "video", "label": "Video"}) + "\n")
    assert job.tasks["video"].status == TaskState.RUNNING
    MocapRunService.handle_line(job, prefix + json.dumps({"event": "progress", "task": "video", "stage": "landmarks",
                                                           "current": 5, "total": 10}))
    assert (job.tasks["video"].current, job.tasks["video"].total) == (5, 10)
    MocapRunService.handle_line(job, "W0000 some mediapipe log line")
    assert job.last_line == "W0000 some mediapipe log line"
    MocapRunService.handle_line(job, prefix + "{broken json")
    MocapRunService.handle_line(job, prefix + json.dumps({"event": "output", "task": "video", "kind": "text",
                                                           "path": "/out/a.txt", "label": "Summary"}))
    assert job.outputs[0]["path"] == "/out/a.txt"
    MocapRunService.handle_line(job, prefix + json.dumps({"event": "task_failed", "task": "video", "message": "boom"}))
    assert job.tasks["video"].status == TaskState.FAILED and job.tasks["video"].message == "boom"


_FAKE_WORKER = textwrap.dedent('''
    import json, os, sys
    job = json.load(open(sys.argv[1], encoding="utf-8"))
    def emit(event, **fields):
        fields["event"] = event
        print("@@MPFB " + json.dumps(fields), flush=True)
    for task in job["tasks"]:
        emit("task_start", task=task["id"], index=0, count=1, label="Fake")
        print("some unrelated log output")
        if task["input"].endswith("fail"):
            emit("task_failed", task=task["id"], message="ValueError: fake failure")
            continue
        path = os.path.join(job["output_dir"], task["id"] + "_summary.txt")
        open(path, "w", encoding="utf-8").write("summary of " + task["id"])
        emit("output", task=task["id"], kind="text", path=path, label="Summary")
        emit("task_done", task=task["id"])
    emit("finished", failures=0)
    sys.exit(1 if any(t["input"].endswith("fail") for t in job["tasks"]) else 0)
''')


def _run_fake(tmp_path, tasks):
    script = tmp_path / "fake_worker.py"
    script.write_text(_FAKE_WORKER, encoding="utf-8")
    spec = {"protocol": 1, "output_dir": str(tmp_path / "run"), "models_dir": "", "tasks": tasks}
    job = MocapRunService.start_run(spec, python=sys.executable, worker_script=str(script))
    job.thread.join(60)
    assert not job.is_running
    return job


def test_whole_run_with_fake_worker(tmp_path):
    job = _run_fake(tmp_path, [{"id": "video", "type": "vision", "input": "clip.mp4"},
                               {"id": "audio", "type": "audio", "input": "speech.wav"}])
    assert job.status == RunJob.SUCCEEDED, (job.error, open(job.log_path, encoding="utf-8").read())
    assert [task.status for task in job.tasks.values()] == [TaskState.DONE, TaskState.DONE]
    assert len(job.outputs) == 2
    assert os.path.isfile(os.path.join(job.run_dir, _MODULE.JOB_FILE))
    assert "some unrelated log output" in open(job.log_path, encoding="utf-8").read()

    MocapRunService.load_results(job)
    name = _MODULE.TEXT_PREFIX + "video_summary.txt"
    assert name in job.loaded_texts
    assert bpy.data.texts[name].as_string() == "summary of video"
    for text_name in job.loaded_texts:
        bpy.data.texts.remove(bpy.data.texts[text_name])


def test_failed_task_fails_the_run_but_not_the_others(tmp_path):
    job = _run_fake(tmp_path, [{"id": "video", "type": "vision", "input": "clip.fail"},
                               {"id": "audio", "type": "audio", "input": "speech.wav"}])
    assert job.status == RunJob.FAILED
    assert job.tasks["video"].status == TaskState.FAILED
    assert job.tasks["audio"].status == TaskState.DONE
    assert "fake failure" in job.error
